<!-- wp:wdl/lw-qa-1 -->
<div class="wp-block-wdl-lw-qa-1 lw-qa-1"><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">撮影に慣れていなくても大丈夫？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">会話をしながら進める撮影をイメージした制作例です。実際の対応方法や担当者は未設定です。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">服装・ヘアメイクは？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">衣装・ヘアメイクの有無や追加料金、着替え・持ち込み条件は未設定です。実際のお申し込み前に確認する想定です。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">写真は自由に使えますか？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">納品写真の商用利用・SNS掲載・二次利用の範囲は未設定です。このページのAI生成画像を実際の撮影実績として使用することは想定していません。</p></div></dd></dl><dl class="lw-qa-1__dl"><dt><div class="label" data-lw_font_set="Roboto" style="font-weight:">Q<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_q"><p data-lw_font_set="" style="font-weight:">このページから予約できますか？</p></div><div class="open_icon" style="background:var(--color-main)"></div></dt><dd><div class="label" data-lw_font_set="Roboto" style="font-weight:;color:var(--color-main)">A<div style="background:var(--color-main)"></div></div><div class="lw-qa-1__text_a"><p data-lw_font_set="" style="font-weight:">架空の制作サンプルのため、実際の予約は受け付けていません。</p></div></dd></dl><script>
(function(){
	const scriptEl  = document.currentScript;
	if ( !scriptEl ) return;
	const container = scriptEl.parentNode;           // <script> の親 = lw-qa-1 本体
	if ( !container || !container.classList.contains('lw-qa-1') ) return;

	/* クリックイベントをバインド ---------------------- */
	function bind () {
		container.querySelectorAll(".lw-qa-1__dl").forEach( function( dl ){
			if ( dl.dataset.lwQaBound ) return;      // 二重バインド防止
			dl.dataset.lwQaBound = "1";
			dl.addEventListener("click", function(){ dl.classList.toggle("active"); } );
		} );
	}

	bind(); // まず 1 回

	/* MutationObserver – QA が動的に増減しても OK */
	const mo = new MutationObserver(bind);
	mo.observe(container,{ childList:true, subtree:true });
})();
		</script></div>
<!-- /wp:wdl/lw-qa-1 -->

